Business Logic (BL) Details:
/**
 * @project     UUM
 * @modul       STUDENT FINANCE / INSURANCE / NEW STUDENT
 * @author      wardatul.sakinah
 * @date        
 * @editor     
 * @history       
 */

include('system_prerequisite.php');

$mode = $_GET['mode']; //main / detail


if($mode == 'main')
{

	// common filter
	$filter = "FROM				".DB2.".student			A  
				LEFT OUTER JOIN	".DB2.".stud_insurance	B 
				ON				A.std_student_id = B.std_student_id 
				WHERE			A.std_sem_level=1 and A.std_mode_study='1' 
				AND CONCAT_WS('__',
					A.std_student_id,							
					A.std_student_name,							
					A.std_program_level,							
					A.std_intake_semester,						
					B.vcs_vendor_code_insuran,					
					B.sin_ins_policy_no,							
					ifnull(B.sin_isinv_issued,'N')	
				) LIKE CONCAT('%', ?, '%')
				";

	// record count
	$sql = "SELECT COUNT(*) C $filter";
	$recordsFiltered = executeQueryV2($sql, [$_POST['search']['value']])[0]['C'];

	// main sql
	$sql = "SELECT	A.std_student_id							Matric,
					A.std_student_name							Nama,
					A.std_program_level							Prog_level,
					A.std_intake_semester						Sems,
					B.vcs_vendor_code_insuran					Ins_inst,
					B.sin_ins_policy_no							Policy1, 
					ifnull(B.sin_isinv_issued,'N')				Status1
				$filter
				ORDER BY {$_POST['orderBy'][0]} {$_POST['orderBy'][1]}
				LIMIT ".$_POST['start'].", ".$_POST['length']."
			"; 
	$data = executeQueryV2($sql, [$_POST['search']['value']]);
}
else if($mode == 'detail' && $_GET['ID'])
{
	// common filter
	$filter = "FROM				".DB2.".receipt_batch_detl
				WHERE			rbm_receipt_batch_master_id = '".$_GET['ID']."'
				AND CONCAT_WS('__',
					std_student_id,									
					rbd_student_name,								
					rbd_student_ic_passport,							
					DATE_FORMAT(rbd_transaction_date,'%d/%m/%Y'),	
					FORMAT(rbd_transaction_amt,2),					
					rbd_transaction_ref									
				) LIKE CONCAT('%', ?, '%')
				";

	// record count
	$sql = "SELECT COUNT(*) C $filter";
	$recordsFiltered = executeQueryV2($sql, [$_POST['search']['value']])[0]['C'];

	// main sql
	$sql = "SELECT	std_student_id									AS STUD_ID,
					rbd_student_name								AS STUD_NAME,
					rbd_student_ic_passport							AS STUD_IC,
					DATE_FORMAT(rbd_transaction_date,'%d/%m/%Y')	AS PAYMENT_DATE,
					FORMAT(rbd_transaction_amt,2)					AS TRANS_AMT,
					rbd_transaction_ref								AS TRANS_REF
				$filter
				ORDER BY {$_POST['orderBy'][0]} {$_POST['orderBy'][1]}
				LIMIT ".$_POST['start'].", ".$_POST['length']."
			"; 
	$data = executeQueryV2($sql, [$_POST['search']['value']]);
}
else if($mode == 'detail_temp')
{
	// common filter
	$filter = "FROM		".DB2.".stud_insurance_info_temp t
				WHERE createdby = '".$_USER['USERNAME']."' and std_student_id!=''  and	CONCAT_WS('__',
					std_student_id,									
					sii_policy_no,								
					vcs_vendor_code_insuran,							
					DATE_FORMAT(sii_ins_cover_from,'%d/%m/%Y'),		
					DATE_FORMAT(sii_ins_cover_to,'%d/%m/%Y'),	
					sii_ins_cover_sems_id_from,
					sii_ins_cover_sems_id_to
				) LIKE CONCAT('%', ?, '%')
				";

	// record count
	$sql = "SELECT COUNT(*) C $filter";
	$recordsFiltered = executeQueryV2($sql, [$_POST['search']['value']])[0]['C'];

	// main sql
	$sql = "SELECT	std_student_id								STUD_ID,
	                (SELECT a.std_student_name FROM ".DB2.".student a where a.std_student_id = t.std_student_id ) STUD_NAME,
					sii_policy_no								POLICY_NO,
					vcs_vendor_code_insuran						ICC,
					DATE_FORMAT(sii_ins_cover_from,'%d/%m/%Y')	START_DATE,
					DATE_FORMAT(sii_ins_cover_to,'%d/%m/%Y')	END_DATE,
					sii_ins_cover_sems_id_from					SEM_START, 
					sii_ins_cover_sems_id_to					SEM_END
				$filter
				ORDER BY {$_POST['orderBy'][0]} {$_POST['orderBy'][1]}
				LIMIT ".$_POST['start'].", ".$_POST['length']."
			"; 
	$data = executeQueryV2($sql, [$_POST['search']['value']]);
}

return [
	'draw'				=> $_POST['draw'],
	'recordsFiltered'	=> $recordsFiltered,
	'data'				=> $data
];

